package dao; import java.sql.*; import negocio.*; public class PerfilJugadorDAOMySQL implements PerfilJugadorDAO { public void guardar(Connection c,PerfilJugador p){validar(p);if(p.getId()<=0)insertar(c,p);else actualizar(c,p);} private void insertar(Connection c,PerfilJugador p){String q="INSERT INTO perfiles_jugador(cliente_id,estado,nombre_publico,posicion_preferida,disponible_para_jugar,acepta_invitaciones,vinculacion_revisada,usuario_revision_id,fecha_revision,activo) VALUES(?,?,?,?,?,?,?,?,?,?)";try(PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){params(s,p);s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())p.setId(r.getLong(1));}}catch(SQLException e){throw error(e);}} private void actualizar(Connection c,PerfilJugador p){String q="UPDATE perfiles_jugador SET cliente_id=?,estado=?,nombre_publico=?,posicion_preferida=?,disponible_para_jugar=?,acepta_invitaciones=?,vinculacion_revisada=?,usuario_revision_id=?,fecha_revision=?,activo=? WHERE id=?";try(PreparedStatement s=c.prepareStatement(q)){params(s,p);s.setLong(11,p.getId());if(s.executeUpdate()==0)throw new IllegalArgumentException("El perfil no existe.");}catch(SQLException e){throw error(e);}} private void params(PreparedStatement s,PerfilJugador p)throws SQLException{if(p.getClienteId()==null)s.setNull(1,Types.BIGINT);else s.setLong(1,p.getClienteId());s.setString(2,p.getEstado().name());s.setString(3,p.getNombrePublico());if(p.getPosicionPreferida()==null)s.setNull(4,Types.VARCHAR);else s.setString(4,p.getPosicionPreferida().name());s.setBoolean(5,p.isDisponibleParaJugar());s.setBoolean(6,p.isAceptaInvitaciones());s.setBoolean(7,p.isVinculacionRevisada());if(p.getUsuarioRevisionId()==null)s.setNull(8,Types.BIGINT);else s.setLong(8,p.getUsuarioRevisionId());if(p.getFechaRevision()==null)s.setNull(9,Types.TIMESTAMP);else s.setTimestamp(9,Timestamp.valueOf(p.getFechaRevision()));s.setBoolean(10,p.isActivo());} public PerfilJugador buscar(Connection c,long id){return one(c," WHERE id=?",id);} public PerfilJugador buscarPorCliente(Connection c,long id){return one(c," WHERE cliente_id=?",id);} private PerfilJugador one(Connection c,String w,long id){String q="SELECT id,cliente_id,estado,nombre_publico,posicion_preferida,disponible_para_jugar,acepta_invitaciones,vinculacion_revisada,usuario_revision_id,fecha_revision,activo,fecha_creacion,fecha_actualizacion FROM perfiles_jugador"+w;try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){if(!r.next())return null;PerfilJugador p=new PerfilJugador();p.setId(r.getLong(1));long x=r.getLong(2);p.setClienteId(r.wasNull()?null:x);p.setEstado(EstadoPerfilJugador.valueOf(r.getString(3)));p.setNombrePublico(r.getString(4));String pos=r.getString(5);if(pos!=null)p.setPosicionPreferida(PosicionJugador.valueOf(pos));p.setDisponibleParaJugar(r.getBoolean(6));p.setAceptaInvitaciones(r.getBoolean(7));p.setVinculacionRevisada(r.getBoolean(8));x=r.getLong(9);p.setUsuarioRevisionId(r.wasNull()?null:x);Timestamp t=r.getTimestamp(10);if(t!=null)p.setFechaRevision(t.toLocalDateTime());p.setActivo(r.getBoolean(11));return p;}}catch(SQLException e){throw new RuntimeException("No se pudo consultar el perfil deportivo.",e);}} private void validar(PerfilJugador p){if(p==null||p.getEstado()==null||p.getNombrePublico()==null||p.getNombrePublico().isBlank())throw new IllegalArgumentException("El perfil deportivo es incompleto.");if((p.getEstado()==EstadoPerfilJugador.DEFINITIVO)!=(p.getClienteId()!=null))throw new IllegalArgumentException("La identidad definitiva requiere cliente y la provisional no lo admite.");p.setNombrePublico(p.getNombrePublico().trim());} private RuntimeException error(SQLException e){return e.getErrorCode()==1062?new IllegalArgumentException("El cliente ya tiene perfil deportivo.",e):new RuntimeException("No se pudo guardar el perfil deportivo.",e);} }
